package com.iare.club.service;
import com.iare.club.entity.*;import com.iare.club.repository.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;
@Service public class InvestmentService{
 private final UserInvestmentRepository investments;private final ProductRepository products;private final WalletRepository wallets;private final WalletService walletService;private final WalletTransactionRepository transactions;private final DailyRewardRepository rewards;private final Clock clock;private final int periodHours;private final RateLimitService limits;private final ReferralService referrals;
 public InvestmentService(UserInvestmentRepository i,ProductRepository p,WalletRepository w,WalletService ws,WalletTransactionRepository t,DailyRewardRepository r,Clock c,RateLimitService limits,ReferralService referrals,@Value("${moneymint.reward.period-hours:24}")int period){investments=i;products=p;wallets=w;walletService=ws;transactions=t;rewards=r;clock=c;this.limits=limits;this.referrals=referrals;periodHours=period;}
 @Transactional public UserInvestment purchase(AppUser user,long productId,String requestReference){limits.check("invest:"+user.getId(),10);if(requestReference==null||requestReference.isBlank())throw new FinanceException("Invalid investment request");Optional<UserInvestment> prior=investments.findByRequestReference(requestReference);if(prior.isPresent()){if(!prior.get().getUser().getId().equals(user.getId()))throw new FinanceException("Invalid investment request");return prior.get();}if(investments.existsByUserIdAndProductId(user.getId(),productId))throw new DuplicatePurchaseException();InvestmentProduct product=products.findById(productId).orElseThrow(()->new FinanceException("Product not found"));if(!product.isActive())throw new FinanceException("This product is not currently active");Wallet wallet=walletService.lock(user);if(investments.existsByUserIdAndProductId(user.getId(),productId))throw new DuplicatePurchaseException();if(wallet.getDepositBalance().compareTo(product.getDiscountPrice())<0)throw new InsufficientDepositException();wallet.debitDeposit(product.getDiscountPrice());UserInvestment investment=investments.saveAndFlush(new UserInvestment(user,product,requestReference,clock.instant(),periodHours));wallets.save(wallet);transactions.save(new WalletTransaction(user,WalletTransaction.Type.INVESTMENT_PURCHASE,WalletTransaction.Status.SUCCESSFUL,product.getDiscountPrice().negate(),wallet.getDepositBalance(),"INV-"+requestReference,"Investment purchased: "+product.getName(),clock.instant()));referrals.rewardFirstPurchase(user,investment);return investment;}
 @Transactional public UserInvestment collectReward(AppUser user,long investmentId){limits.check("reward:"+user.getId(),20);UserInvestment investment=investments.findByIdForUpdate(investmentId).orElseThrow(()->new FinanceException("Investment not found"));if(!investment.getUser().getId().equals(user.getId()))throw new FinanceException("Investment not found");if(investment.getStatus()!=UserInvestment.Status.ACTIVE)throw new FinanceException("This investment has completed");Instant now=clock.instant();if(investment.getRewardsCollected()>0&&now.isBefore(investment.getNextRewardAt()))throw new RewardNotReadyException(investment.getNextRewardAt());int number=investment.getRewardsCollected()+1;if(rewards.existsByInvestmentIdAndRewardNumber(investmentId,number))throw new FinanceException("This reward was already collected");Wallet wallet=walletService.lock(user);rewards.save(new DailyReward(investment,user,number,investment.getDailyReward(),now));investment.collect(now.plusSeconds(periodHours*3600L));wallet.creditReward(investment.getDailyReward());wallets.save(wallet);investments.save(investment);String ref="RWD-"+investmentId+"-"+number;transactions.save(new WalletTransaction(user,WalletTransaction.Type.DAILY_REWARD,WalletTransaction.Status.SUCCESSFUL,investment.getDailyReward(),wallet.getRewardBalance(),ref,"Daily reward collected for "+investment.getProductName(),now));return investment;}
 @Transactional(readOnly=true) public List<UserInvestment> findFor(AppUser user){return investments.findTop100ByUserIdOrderByPurchasedAtDesc(user.getId());}
 @Transactional(readOnly=true) public Set<Long> purchasedProductIds(AppUser user){return Set.copyOf(investments.findProductIdsByUserId(user.getId()));}
 public String newRequestReference(){return UUID.randomUUID().toString();}
 public Instant now(){return clock.instant();}
 public static class FinanceException extends RuntimeException{public FinanceException(String m){super(m);}} public static class InsufficientDepositException extends FinanceException{public InsufficientDepositException(){super("Insufficient deposit balance");}} public static class DuplicatePurchaseException extends FinanceException{public DuplicatePurchaseException(){super("You have already purchased this product");}} public static class RewardNotReadyException extends FinanceException{private final Instant availableAt;public RewardNotReadyException(Instant at){super("The next reward is not available yet");availableAt=at;}public Instant getAvailableAt(){return availableAt;}}
}
